const first = $input.first()?.json;
let rows = [];
if (Array.isArray(first)) rows = first;
else if (Array.isArray(first?.body)) rows = first.body;
else rows = $input.all().map(i => i.json).filter(o => o && o.asset_id);
const valid = rows.filter(r => r && r.asset_id && r.description && r.description.trim().length > 10);
if (valid.length === 0) return [];
const sanitize = (s) => String(s).replace(/[\x00-\x1F]/g, ' ').substring(0, 3000);
const texts = valid.map(r => sanitize(r.description));
const metadata = valid.map(r => ({ asset_id: r.asset_id, asset_type: r.asset_type, origen: r.origen }));
return [{ json: { texts, metadata, count: valid.length }}];

const resp = $input.first()?.json;
if (!resp || !Array.isArray(resp.data) || resp.data.length === 0) return [{ json: { payload: [], count: 0 }}];
const meta = $('Build Embedding Input').first().json.metadata;
const sorted = resp.data.slice().sort((a, b) => a.index - b.index);
const payload = meta.map((m, i) => ({
  asset_id: m.asset_id,
  embedding: sorted[i] && sorted[i].embedding
})).filter(x => Array.isArray(x.embedding) && x.embedding.length === 1536);
return [{ json: { payload, count: payload.length }}];

const first = $input.first()?.json;
let rows = [];
if (Array.isArray(first)) rows = first;
else if (Array.isArray(first?.body)) rows = first.body;
else rows = $input.all().map(i => i.json).filter(o => o && o.asset_id);
const matched = rows.filter(r => r && r.matched === true);
const unmatched = rows.filter(r => r && r.matched === false);
const avgScore = matched.length > 0 ? (matched.reduce((s, r) => s + Number(r.match_score || 0), 0) / matched.length) : 0;
const maxScore = matched.length > 0 ? Math.max.apply(null, matched.map(r => Number(r.match_score || 0))) : 0;
const minScore = matched.length > 0 ? Math.min.apply(null, matched.map(r => Number(r.match_score || 0))) : 0;
const belowThresholdAvg = unmatched.length > 0 ? (unmatched.reduce((s, r) => s + Number(r.match_score || 0), 0) / unmatched.length) : 0;
return [{ json: {
  total_evaluados: rows.length,
  matched: matched.length,
  unmatched: unmatched.length,
  avg_score_matched: Number(avgScore.toFixed(4)),
  max_score_matched: Number(maxScore.toFixed(4)),
  min_score_matched: Number(minScore.toFixed(4)),
  avg_score_below_threshold: Number(belowThresholdAvg.toFixed(4))
}}];
